///|
fn server_env_value(value : String, root : String) -> String raise {
  let result = StringBuilder()
  let mut remaining = value
  while remaining.split_once("${") is Some((prefix, expression)) {
    result.write_string(quote(prefix.to_owned()))
    guard expression.split_once("}") is Some((variable, suffix)) else {
      raise AdapterError("Invalid saved server environment reference")
    }
    let reference = variable.to_owned()
    let required = reference.has_suffix("?")
    let name = if required {
      reference[:reference.length() - 1].to_owned()
    } else {
      reference
    }
    ignore(
      interpolate("${" + reference + "}", _ => Some(""), "server environment"),
    )
    if name == "DEVSY_REMOTE_WORKSPACE_FOLDER" {
      result.write_string(quote(root))
    } else {
      result.write_string(
        "\"${" + name + (if required { "?" } else { "-" }) + "}\"",
      )
    }
    remaining = suffix.to_owned()
  }
  result.write_string(quote(remaining))
  result.to_string()
}

///|
fn server_launch_script(
  root : String,
  port : Int32,
  server_env : Json,
) -> String raise {
  let assignments = StringBuilder()
  let variable_names = []
  if server_env is Json::Object(values) {
    for name, value in values {
      guard valid_env_name(name) else {
        raise AdapterError("Invalid saved server environment name")
      }
      ignore(
        interpolate("${" + name + "}", _ => Some(""), "server environment"),
      )
      guard value is Json::String(text) && !text.contains("\u0000") else {
        raise AdapterError("Invalid saved server environment")
      }
      assignments.write_string(" " + server_env_value(text, root))
      variable_names.push(Json::string(name))
    }
  } else {
    raise AdapterError("Invalid saved server environment")
  }

  // The Linux wrapper in 1.4.224 resolves the app root inside app.asar.unpacked.
  // Invoke the package-declared CLI entry so Orca prepares its bundled orcad.
  if assignments.to_string() == "" {
    return "ELECTRON_RUN_AS_NODE=1 exec \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" \"$HOME/.local/share/orca-env-devsy/orca/current/resources/app.asar/out/cli/index.js\" serve --recipe-json --project-root " +
      quote(root) +
      " --port 47121 --pairing-address " +
      quote("ws://127.0.0.1:\{port}") +
      " 2>/dev/null"
  }
  let launcher =
    #|const fs = require("fs");
    #|const cp = require("child_process");
    #|const names = JSON.parse(process.argv[1]);
    #|const values = fs.readFileSync(0).toString().split("\0");
    #|const environment = {...process.env, ELECTRON_RUN_AS_NODE: "1"};
    #|names.forEach((name, index) => { environment[name] = values[index]; });
    #|const cli = process.env.HOME + "/.local/share/orca-env-devsy/orca/current/resources/app.asar/out/cli/index.js";
    #|const result = cp.spawnSync(process.execPath, [cli, "serve", "--recipe-json", "--project-root", process.argv[2], "--port", "47121", "--pairing-address", process.argv[3]], {env: environment, stdio: ["ignore", "inherit", "ignore"]});
    #|if (result.error) process.exit(1);
    #|process.exit(result.status === null ? 1 : result.status);
  "set --" +
  assignments.to_string() +
  "; printf '%s\\0' \"$@\" | ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" -e " +
  quote(launcher) +
  " " +
  quote(Json::array(variable_names).stringify()) +
  " " +
  quote(root) +
  " " +
  quote("ws://127.0.0.1:\{port}") +
  " 2>/dev/null"
}

